function validate([matrix]) {
  if (!Array.isArray(matrix) || matrix.length < 1 || matrix.length > 500) return 'matrix needs 1 to 500 rows.';
  const n = matrix[0].length;
  if (n < 1 || n > 500) return 'Each row needs 1 to 500 values.';
  for (const row of matrix) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < -1000000000 || v > 1000000000)) return 'Each value is an integer from -10^9 to 10^9.';
  }
  return null;
}

