function matrixRankTransform(matrix) {
  const rows = matrix.length;
  const cols = matrix[0].length;
  const cells = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      cells.push([matrix[r][c], r, c]);
    }
  }
  cells.sort((a, b) => a[0] - b[0]);
  const rowRank = new Array(rows).fill(0);
  const colRank = new Array(cols).fill(0);
  const answer = Array.from({ length: rows }, () => new Array(cols).fill(0));
  const parent = Array.from({ length: rows + cols }, (_, i) => i);
  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }
  let start = 0;
  while (start < cells.length) {
    let end = start;
    while (end < cells.length && cells[end][0] === cells[start][0]) {
      end++;
    }
    for (let k = start; k < end; k++) {
      const [, r, c] = cells[k];
      parent[find(r)] = find(rows + c);
    }
    const groupRank = new Map();
    for (let k = start; k < end; k++) {
      const [, r, c] = cells[k];
      const root = find(r);
      const need = Math.max(rowRank[r], colRank[c]) + 1;
      groupRank.set(root, Math.max(groupRank.get(root) ?? 0, need));
    }
    for (let k = start; k < end; k++) {
      const [, r, c] = cells[k];
      const rank = groupRank.get(find(r));
      answer[r][c] = rank;
      rowRank[r] = rank;
      colRank[c] = rank;
    }
    for (let k = start; k < end; k++) {
      const [, r, c] = cells[k];
      parent[r] = r;
      parent[rows + c] = rows + c;
    }
    start = end;
  }
  return answer;
}

