function matrixRankTransform(matrix) {
  const m = matrix.length, n = matrix[0].length;
  const rank = matrix.map(row => row.map(() => 1));
  // Raise ranks until every row/column rule holds; starting at 1 and only raising gives the smallest valid ranks.
  let changed = true;
  while (changed) {
    changed = false;
    for (let a = 0; a < m * n; a++) {
      for (let b = 0; b < m * n; b++) {
        const ar = Math.floor(a / n), ac = a % n, br = Math.floor(b / n), bc = b % n;
        if (a === b || (ar !== br && ac !== bc)) continue;
        const p = matrix[ar][ac], q = matrix[br][bc];
        let want = rank[br][bc];
        if (p < q) want = Math.max(want, rank[ar][ac] + 1);
        if (p === q) want = Math.max(want, rank[ar][ac]);
        if (want !== rank[br][bc]) { rank[br][bc] = want; changed = true; }
      }
    }
  }
  return rank;
}

