function generate(rand, size) {
  const big = size === 'large';
  const m = big ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const n = big ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const spans = big ? [20, 1000, 1000000000] : [1, 3, 10, 1000000000];
  const span = spans[Math.floor(rand() * spans.length)];
  const matrix = Array.from({ length: m }, () => Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span));
  return [matrix];
}
